import {preparePublication,verifyPublicationReceipt} from './publishing.mjs';
import {savedReport} from './destination-revisions.mjs';
import {packageProblems} from './transfer-core.mjs';
const $=id=>document.getElementById(id);let state={},busy=false;
const url=new URL(location.href),id=url.searchParams.get('publication')||crypto.randomUUID();url.searchParams.set('publication',id);history.replaceState(null,'',url);const key='lesson-publication-'+id;
function persist(){localStorage.setItem(key,JSON.stringify(state));}
function clearResult(){delete state.report;delete state.objectiveTargets;delete state.mappingDirty;delete state.preflight;delete state.verification;$('receipt-status').textContent='Import the completed companion report after saving.';}
function render(){
 $('package-summary').textContent=state.pkg?state.pkg.lesson.title+' · '+(packageProblems(state.pkg).length?'Approval needs attention.':'Approved locally.'):'Choose an approved lesson package.';
 const preflight=state.preflight;$('preflight').replaceChildren();if(preflight){const title=document.createElement('h3');title.textContent=state.verification?'Publication complete and verified':preflight.status==='already-matches'?'The lesson already matches. No save is needed.':preflight.status==='blocked'?'Resolve these items before publishing':'Ready for the companion’s final checks';$('preflight').append(title);
  for(const text of [...preflight.blockers,...preflight.checks,...preflight.changes.map(change=>change.label)]){const paragraph=document.createElement('p');paragraph.textContent=text;$('preflight').append(paragraph);}
  const note=document.createElement('p');note.textContent=preflight.existingLevels+' existing level associations are present in the checked baseline.';$('preflight').append(note);
 }
 const choices=preflight?.objectiveChoices,canMap=!!state.report&&choices?.saved.length>0&&choices.saved.length===choices.proposed.length&&!state.verification;
 $('objective-review').hidden=!canMap;$('objective-mappings').replaceChildren();
 if(canMap)for(const saved of choices.saved){const label=document.createElement('label');label.textContent=saved.description+' ('+saved.tagCount+' level tags retained)';const select=document.createElement('select');select.dataset.objectiveId=String(saved.id);select.disabled=busy;const blank=document.createElement('option');blank.value='';blank.textContent='Choose an imported objective';select.append(blank);for(const [index,text]of choices.proposed.entries()){const option=document.createElement('option');option.value=String(index);option.textContent=(index+1)+'. '+text;select.append(option);}const target=state.objectiveTargets?.find(t=>t.destinationId===saved.id);select.value=target?String(target.sourceIndex):'';select.onchange=()=>{state.objectiveTargets=(state.objectiveTargets||[]).filter(t=>t.destinationId!==saved.id);if(select.value!=='')state.objectiveTargets.push({destinationId:saved.id,sourceIndex:Number(select.value)});state.mappingDirty=true;persist();$('download-package').disabled=true;$('receipt').disabled=true;$('handoff-help').textContent='Confirm the changed objective mappings before downloading.';};label.append(select);$('objective-mappings').append(label);}
 $('confirm-objectives').disabled=busy||!canMap;
 const ready=preflight?.status==='ready-for-companion-review'&&!state.mappingDirty;$('package').disabled=busy||!!state.verification;$('baseline').disabled=busy||!!state.verification;$('download-package').disabled=!ready||busy||!!state.verification;$('receipt').disabled=!ready||busy;$('destination').hidden=!preflight;if(preflight)$('destination').href=preflight.destination.url;
 $('next').hidden=!state.verification;$('handoff-help').textContent=state.verification?'This publication is complete. Do not send the package again. Start a separate review for later changes.':ready?'Download this exact package and load it in the companion on the checked lesson.':preflight?.status==='already-matches'?'No publishing action is required.':'Resolve the listed blockers in the workspace, then approve and check again.';
 if(state.verification)$('receipt-status').textContent=`Saved and independently verified: ${state.verification.counts.levels} levels, ${state.verification.counts.sections} sections. No second save was sent.`;
}
async function readFile(file){if(!file)return null;if(file.size>32_000_000)throw Error('Choose a report smaller than 32 MB.');return JSON.parse(await file.text());}
async function run(action){if(busy)return;busy=true;$('download-package').disabled=true;for(const name of ['package','baseline','receipt'])$(name).disabled=true;try{await action();persist();render();}catch(error){$('status').textContent=error.message;}finally{busy=false;$('package').disabled=false;$('baseline').disabled=false;render();}}
$('package').onchange=event=>run(async()=>{const pkg=await readFile(event.target.files[0]);if(!pkg)return;const problems=packageProblems(pkg);if(problems.length)throw Error(problems.join(' '));state.pkg=pkg;clearResult();$('status').textContent='Approved package loaded. Read the saved destination next.';});
$('baseline').onchange=event=>run(async()=>{if(!state.pkg)throw Error('Choose an approved package first.');const report=await readFile(event.target.files[0]);if(!report)return;const result=await preparePublication(state.pkg,report);const baseline=await savedReport(report);state.report={mode:'native',destination:baseline.destination,checkpoint:{status:'baseline-read',freshSaved:baseline.saved}};state.preflight=result;delete state.objectiveTargets;delete state.mappingDirty;delete state.verification;$('status').textContent='Destination checked without changing the live lesson.';});
$('confirm-objectives').onclick=()=>run(async()=>{if(!state.report||!state.pkg||state.verification)throw Error('Read the saved destination first.');const result=await preparePublication(state.pkg,state.report,{objectiveTargets:state.objectiveTargets||[]});state.preflight=result;state.mappingDirty=false;$('status').textContent=result.status==='blocked'?'Mappings need attention. Resolve the listed items.':'Objective mappings checked. Review the changes before downloading.';});
$('download-package').onclick=()=>{if(busy||state.mappingDirty||state.verification||state.preflight?.status!=='ready-for-companion-review')return;const link=document.createElement('a'),blob=URL.createObjectURL(new Blob([JSON.stringify(state.preflight.handoff,null,2)],{type:'application/json'}));link.href=blob;link.download='lesson-publication-package.json';link.click();setTimeout(()=>URL.revokeObjectURL(blob),1000);};
$('receipt').onchange=event=>run(async()=>{if(state.mappingDirty)throw Error('Confirm objective mappings first.');const report=await readFile(event.target.files[0]);if(!report)return;state.verification=await verifyPublicationReceipt(state.preflight.handoff,report);$('status').textContent='Publication receipt verified against this approved package.';});
try{state=JSON.parse(localStorage.getItem(key))||{};const pending=sessionStorage.getItem('lesson-publication-input');if(!state.pkg&&pending){const parsed=JSON.parse(pending);const problems=packageProblems(parsed);if(problems.length)throw Error(problems.join(' '));state.pkg=parsed;persist();sessionStorage.removeItem('lesson-publication-input');}render();}catch(error){$('status').textContent=error.message;}
